for name,changes in PATCHES.items():
    path=Path(name)
    source=path.read_text(encoding="utf-8")
    for old,replacement in changes:
        assert source.count(old)==1,(name,old[:100])
        source=source.replace(old,replacement)
    path.write_text(source,encoding="utf-8")
runner=Path("gallery/tests/test_history_row_maintenance.py")
hook="\n# Mandatory A2.1 ownership and teardown regression in both motion modes.\nsubprocess.run([sys.executable,str(Path(__file__).resolve().parents[1]/'audits'/'2026-11-16-a2-player-session-ownership-regression.py'),sys.argv[1]],check=True)\n"
raw=runner.read_text(encoding="utf-8")
assert hook not in raw
runner.write_text(raw+hook,encoding="utf-8")
print("PASS guarded A2.1 session ownership source edits",flush=True)
